            } elseif (preg_match('/[\%\*]/', $pathRelative)) {
                $pathRelative = str_replace('*', '%', $pathRelative);
                $comparison = Criteria::LIKE;
            }
        }

        return $this->addUsingAlias(EmailAttachmentPeer::PATH_RELATIVE, $pathRelative, $comparison);
    }

    /**
     * Filter the query on the CREATE_AT column
     *
     * Example usage:
     * <code>
     * $query->filterByCreateAt('2011-03-14'); // WHERE CREATE_AT = '2011-03-14'
     * $query->filterByCreateAt('now'); // WHERE CREATE_AT = '2011-03-14'
     * $query->filterByCreateAt(array('max' => 'yesterday')); // WHERE CREATE_AT < '2011-03-13'
     * </code>
     *
     * @param     mixed $createAt The value to use as filter.
     *              Values can be integers (unix timestamps), DateTime objects, or strings.
     *              Empty strings are treated as NULL.
     *              Use scalar values for equality.
     *              Use array values for in_array() equivalent.
     *              Use associative array('min' => $minValue, 'max' => $maxValue) for intervals.
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return EmailAttachmentQuery The current query, for fluid interface
     */
    public function filterByCreateAt($createAt = null, $comparison = null)
    {
        if (is_array($createAt)) {
            $useMinMax = false;
            if (isset($createAt['min'])) {
                $this->addUsingAlias(EmailAttachmentPeer::CREATE_AT, $createAt['min'], Criteria::GREATER_EQUAL);
                $useMinMax = true;
            }
            if (isset($createAt['max'])) {
                $this->addUsingAlias(EmailAttachmentPeer::CREATE_AT, $createAt['max'], Criteria::LESS_EQUAL);
                $useMinMax = true;
            }
            if ($useMinMax) {
                return $this;
            }
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }
        }

        return $this->addUsingAlias(EmailAttachmentPeer::CREATE_AT, $createAt, $comparison);
    }

    /**
     * Filter the query by a related Email object
     *
     * @param   Email|PropelObjectCollection $email The related object(s) to use as filter
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return                 EmailAttachmentQuery The current query, for fluid interface
     * @throws PropelException - if the provided filter is invalid.
     */
    public function filterByEmail($email, $comparison = null)
    {
        if ($email instanceof Email) {
            return $this
                ->addUsingAlias(EmailAttachmentPeer::EMAIL_ID, $email->getEmailId(), $comparison);
        } elseif ($email instanceof PropelObjectCollection) {
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }

            return $this
                ->addUsingAlias(EmailAttachmentPeer::EMAIL_ID, $email->toKeyValue('PrimaryKey', 'EmailId'), $comparison);
        } else {
            throw new PropelException('filterByEmail() only accepts arguments of type Email or PropelCollection');
        }
    }

    /**
     * Adds a JOIN clause to the query using the Email relation
     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return EmailAttachmentQuery The current query, for fluid interface
     */
    public function joinEmail($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('Email');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'Email');
        }

        return $this;
    }

    /**
     * Use the Email relation Email object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   EmailQuery A secondary query class using the current class as primary query
     */
    public function useEmailQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinEmail($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Email', 'EmailQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   EmailAttachment $emailAttachment Object to remove from the list of results
     *
     * @return EmailAttachmentQuery The current query, for fluid interface
     */
    public function prune($emailAttachment = null)
    {
        if ($emailAttachment) {
            $this->addUsingAlias(EmailAttachmentPeer::EMAILATTAHCMENT_ID, $emailAttachment->getEmailattachmentId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
